"""Diagnostic SAME-WORLD evaluated assembly copy; never a fitted production candidate."""
from pathlib import Path
import bpy,numpy as np,json,hashlib
def apply(folder):
 P=Path(folder);cfg=json.loads((P/'identity-assembly.json').read_text());file=P/'identity-assembly.npz';assert hashlib.sha256(file.read_bytes()).hexdigest()==cfg['payload_sha256'];payload=np.load(file);ids=payload['source_faces'];source=bpy.data.objects['MIA_V17_PIXAL_DetailedHair'];original=source.data;assert hashlib.sha256(np.array([v.co[:] for v in original.vertices],np.float32).tobytes()).hexdigest()==cfg['source_main_co_sha256'];assert np.array_equal(np.array([original.polygons[int(i)].vertices[:] for i in ids]),payload['source_triangles']);bpy.context.view_layer.update();ev=source.evaluated_get(bpy.context.evaluated_depsgraph_get());sm=ev.to_mesh(preserve_all_data_layers=True,depsgraph=bpy.context.evaluated_depsgraph_get());assert len(sm.vertices)==len(original.vertices) and len(sm.polygons)==len(original.polygons);used=np.unique(np.array([sm.polygons[int(i)].vertices[:] for i in ids]));index={int(v):i for i,v in enumerate(used)};co=np.array([sm.vertices[int(v)].co[:] for v in used],np.float32);faces=[[index[int(v)] for v in sm.polygons[int(i)].vertices] for i in ids];loops=np.array([li for i in ids for li in sm.polygons[int(i)].loop_indices],np.int32);normal=np.array([sm.corner_normals[int(li)].vector[:] for li in loops],np.float32);me=bpy.data.meshes.new('MIA_Identity_ExteriorLooseSide');me.from_pydata(co.tolist(),[],faces);me.update();ob=bpy.data.objects.new(me.name,me);bpy.context.scene.collection.objects.link(ob);ob.matrix_world=source.matrix_world.copy();ob.color=source.color;ob.pass_index=source.pass_index
 for prop in ['visible_camera','visible_shadow','visible_diffuse','visible_glossy','visible_transmission','visible_volume_scatter','shadow_terminator_geometry_offset','shadow_terminator_shading_offset']:
  if hasattr(source,prop):setattr(ob,prop,getattr(source,prop))
 me.use_auto_texspace=False;me.texspace_location=original.texspace_location[:];me.texspace_size=original.texspace_size[:]
 for ma in original.materials:me.materials.append(ma)
 for p,i in zip(me.polygons,ids):p.material_index=sm.polygons[int(i)].material_index;p.use_smooth=sm.polygons[int(i)].use_smooth
 uvchecks=[]
 for layer in sm.uv_layers:
  u=me.uv_layers.new(name=layer.name);old=np.array([layer.data[int(i)].uv[:] for i in loops],np.float32);u.data.foreach_set('uv',old.ravel());assert np.array_equal(old,np.array([x.uv[:] for x in u.data],np.float32));uvchecks.append(layer.name)
 me.uv_layers.active_index=original.uv_layers.active_index;me.uv_layers[next(u.name for u in original.uv_layers if u.active_render)].active_render=True;fields=[]
 for a in sm.attributes:
  if a.domain!='POINT' or a.name=='position':continue
  prop='color' if a.data_type in ['FLOAT_COLOR','BYTE_COLOR'] else 'vector' if a.data_type=='FLOAT_VECTOR' else 'value';values=np.array([getattr(a.data[int(i)],prop) for i in used]);target=me.attributes.get(a.name) or me.attributes.new(name=a.name,type=a.data_type,domain='POINT');target.data.foreach_set(prop,values.astype(np.float32 if a.data_type not in ['INT','BOOLEAN'] else np.int32).ravel());assert np.array_equal(values,np.array([getattr(x,prop) for x in target.data]));fields.append(a.name)
 me.normals_split_custom_set(normal.tolist());actual=np.array([x.vector[:] for x in me.corner_normals],np.float32);normal_error=float(np.linalg.norm(actual-normal,axis=1).max());assert normal_error<.0005,normal_error;source_indices=np.array([p.material_index for p in original.polygons]);ev.to_mesh_clear();mask=bpy.data.materials.new('MIA_IDENTITY_ONLY_OriginalAssemblyTemporarilyHidden');mask.use_nodes=True;n=mask.node_tree.nodes;n.clear();bs=n.new('ShaderNodeBsdfTransparent');out=n.new('ShaderNodeOutputMaterial');mask.node_tree.links.new(bs.outputs[0],out.inputs['Surface']);mask.surface_render_method='DITHERED';slot=len(original.materials);original.materials.append(mask)
 for i in ids:original.polygons[int(i)].material_index=slot
 bpy.context.view_layer.update();report=dict(purpose='SAME_WORLD_IDENTITY_DIAGNOSTIC_ONLY; no morph, cap, smoothing or fit',object=ob.name,source_faces=len(ids),source_vertices=len(used),world_matrix=list(map(list,ob.matrix_world)),same_source_world_transform=True,evaluated_source_coordinates_bit_exact=True,all_cornerUVs_bit_exact=uvchecks,all_paint_POINT_fields_bit_exact=fields,original_actual_evaluated_corner_normals_max_decode_error=normal_error,active_render_UV=next(u.name for u in me.uv_layers if u.active_render),texture_space=dict(location=me.texspace_location[:],size=me.texspace_size[:],source_original_bounds_preserved=True),original_material_graphs_shared_unchanged=True,source_original_face_indices_temporarily_changed_only_in_offline_test=True,source_hidden_material_slot=slot,native_saved=False,ART=False);(P/'identity-copy-CPU-report.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8');return report
